const pipeline = $('Pipeline Stage Counts').all().map(i => i.json);
const kpis = $('Dashboard KPIs').first().json;
const agents = $('Agent Performance').all().map(i => i.json);

const pipelineRows = pipeline.map(p => 
  `<tr><td style="padding:8px 12px;border-bottom:1px solid #eee;">${p.status}</td><td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:center;">${p.lead_count}</td><td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:center;">${p.avg_score || '-'}</td></tr>`
).join('');

const agentRows = agents.map(a =>
  `<tr><td style="padding:8px 12px;border-bottom:1px solid #eee;">${a.full_name}</td><td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:center;">${a.current_lead_count || 0}</td><td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:center;">${a.role}</td></tr>`
).join('');

const html = `
<!DOCTYPE html>
<html>
<head><style>
  body { font-family: 'Segoe UI', sans-serif; background: #f5f5f5; padding: 20px; }
  .container { max-width: 600px; margin: 0 auto; background: #fff; border-radius: 12px; overflow: hidden; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
  .header { background: #0E0F11; color: #C9A84C; padding: 24px; text-align: center; }
  .header h1 { margin: 0; font-size: 22px; }
  .header p { margin: 4px 0 0; color: #9B9890; font-size: 13px; }
  .kpis { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 1px; background: #eee; }
  .kpi { background: #fff; padding: 16px; text-align: center; }
  .kpi-val { font-size: 24px; font-weight: 700; color: #0E0F11; }
  .kpi-label { font-size: 11px; color: #666; text-transform: uppercase; letter-spacing: 0.05em; margin-top: 4px; }
  .section { padding: 20px 24px; }
  .section h2 { font-size: 14px; color: #333; margin: 0 0 12px; }
  table { width: 100%; border-collapse: collapse; }
  th { font-size: 11px; color: #666; text-transform: uppercase; letter-spacing: 0.05em; padding: 8px 12px; border-bottom: 2px solid #eee; text-align: left; }
  .footer { padding: 16px 24px; text-align: center; background: #f9f9f9; color: #999; font-size: 11px; }
</style></head>
<body>
<div class="container">
  <div class="header">
    <h1>AUTOIQ × Weekly Report</h1>
    <p>Week ending ${new Date().toLocaleDateString('en-AE', { year: 'numeric', month: 'long', day: 'numeric' })}</p>
  </div>
  <div class="kpis">
    <div class="kpi"><div class="kpi-val">${kpis.total_leads || 0}</div><div class="kpi-label">Total Leads</div></div>
    <div class="kpi"><div class="kpi-val">${kpis.hot_leads || 0}</div><div class="kpi-label">Hot Leads</div></div>
    <div class="kpi"><div class="kpi-val">${kpis.won_this_month || 0}</div><div class="kpi-label">Won This Month</div></div>
  </div>
  <div class="kpis" style="border-top:1px solid #eee;">
    <div class="kpi"><div class="kpi-val">AED ${((kpis.pipeline_value_aed || 0) / 1000).toFixed(0)}K</div><div class="kpi-label">Pipeline Value</div></div>
    <div class="kpi"><div class="kpi-val">${kpis.followups_due_today || 0}</div><div class="kpi-label">Follow-ups Due</div></div>
    <div class="kpi"><div class="kpi-val">${kpis.followups_overdue || 0}</div><div class="kpi-label">Overdue</div></div>
  </div>
  <div class="section">
    <h2>Pipeline Breakdown</h2>
    <table><thead><tr><th>Stage</th><th style="text-align:center;">Count</th><th style="text-align:center;">Avg Score</th></tr></thead><tbody>${pipelineRows}</tbody></table>
  </div>
  <div class="section">
    <h2>Agent Overview</h2>
    <table><thead><tr><th>Agent</th><th style="text-align:center;">Active Leads</th><th style="text-align:center;">Role</th></tr></thead><tbody>${agentRows}</tbody></table>
  </div>
  <div class="footer">AutoIQ CRM &mdash; Generated automatically</div>
</div>
</body></html>
`;

return [{ json: { html, subject: `AutoIQ Weekly Report - ${new Date().toLocaleDateString('en-AE')}` } }];
